import requests
import re

# Search for the Spanish town gas explosion that occurred in July 2008
url = 'https://en.wikipedia.org/wiki/2008_Spanish_town_gas_explosion'
response = requests.get(url)
print('Spanish town gas explosion details:')

if response.status_code == 200:
    # Extract key information
    if 'July 2008' in response.text:
        print('Confirmed: July 2008 event')

    # Look for explosion details and yield
    if 'explosion' in response.text:
        print('Explosion mentioned in article')

    # Look for casualties or impact
    casualties = re.findall(r'\\d+\\s*(killed|dead|casualties)', response.text, re.IGNORECASE)
    if casualties:
        print(f'Casualties mentioned: {casualties}')

    # Look for any mention of explosive force or yield
    yield_matches = re.findall(r'\\d+\\s*(tons|tonnes|kilotons|megatons)', response.text, re.IGNORECASE)
    if yield_matches:
        print(f'Explosive force mentioned: {yield_matches}')

    # Now search for this specific event on Phys.org
    search_url = 'https://www.google.com/search?q=Spanish+town+gas+explosion+2008+site:phys.org'
    headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36'}
    search_response = requests.get(search_url, headers=headers)

    if 'phys.org' in search_response.text:
        print('Found Phys.org article about this event!')
        phys_links = re.findall(r'https://phys\.org/[^\s\"<>]+', search_response.text)
        for link in phys_links[:3]:
            print(f'Phys.org link: {link}')
            # Try to access the article
            try:
                article_response = requests.get(link, headers=headers, timeout=5)
                if article_response.status_code == 200:
                    print(f'Successfully accessed: {link}')
            except:
                print(f'Could not access: {link}')
    else:
        print('No Phys.org article found for Spanish town gas explosion')
else:
    print('Could not access Spanish town gas explosion Wikipedia page')
""}

