import requests
import re

# Search for major industrial explosions in 2008
search_terms = [
    'industrial explosion 2008',
    'pipeline explosion 2008', 
    'chemical explosion 2008',
    'gas explosion 2008',
    'factory explosion 2008'
]

for term in search_terms:
    print(f'Searching for: {term}')

    # Try Wikipedia
    wiki_url = f'https://en.wikipedia.org/wiki/{term.replace(\" \", \"_\")}'
    try:
        response = requests.get(wiki_url, timeout=5)
        if response.status_code == 200:
            # Look for July 2008 mentions
            if 'July 2008' in response.text:
                print(f'  *** FOUND July 2008 event for {term} ***')
                # Extract key details
                soup = response.text
                title_match = re.search(r'<title[^>]*>([^<]*)</title>', soup)
                if title_match:
                    print(f'  Title: {title_match.group(1)}')

                # Look for explosion details
                explosion_matches = re.findall(r'\\d+\\s*(tons|tonnes|kilotons|megatons)', soup, re.IGNORECASE)
                if explosion_matches:
                    print(f'  Explosive force: {explosion_matches}')

                # Look for casualties
                casualty_matches = re.findall(r'\\d+\\s*(killed|dead|casualties)', soup, re.IGNORECASE)
                if casualty_matches:
                    print(f'  Casualties: {casualty_matches}')
    except:
        pass

    # Search Phys.org for this term
    search_url = f'https://www.google.com/search?q={term}+site:phys.org'
    headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36'}

    try:
        search_response = requests.get(search_url, headers=headers, timeout=5)
        if 'phys.org' in search_response.text:
            print(f'  Phys.org mentions found for {term}')
            phys_links = re.findall(r'https://phys\\.org/[^\s\"<>]+', search_response.text)
            for link in phys_links[:2]:
                print(f'    {link}')
    except:
        pass

    print('---')
""}

