import requests
import re
from bs4 import BeautifulSoup

# Try to access specific Phys.org articles about explosions in 2008
urls_to_try = [
    'https://phys.org/news/2008-07-15-gas-explosion.html',  # Guess based on date
    'https://phys.org/news/2008-07-industrial-explosion.html',  # Guess
    'https://phys.org/news/2008-07-chemical-explosion.html'  # Guess
]

headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36'}

for url in urls_to_try:
    print(f'Trying: {url}')
    try:
        response = requests.get(url, headers=headers, timeout=10)
        if response.status_code == 200:
            soup = BeautifulSoup(response.content, 'html.parser')

            # Check if it mentions July 15, 2008
            if 'July 15, 2008' in response.text or '2008-07-15' in response.text:
                print(f'*** FOUND July 15, 2008 article! ***')

                # Extract title
                title = soup.find('h1')
                if title:
                    print(f'Title: {title.get_text().strip()}')

                # Extract main content
                content = soup.find('div', class_='article-content') or soup.find('div', class_='content') or soup.find('div')
                if content:
                    text = content.get_text()
                    print('Content preview:')
                    print(text[:500] + '...' if len(text) > 500 else text)

                # Look for explosion details
                explosion_matches = re.findall(r'\\d+\\s*(tons|tonnes|kilotons|megatons)', text, re.IGNORECASE)
                if explosion_matches:
                    print(f'Explosive force mentioned: {explosion_matches}')

                break
            else:
                print('Not July 15, 2008 article')
        else:
            print(f'Failed to access: {response.status_code}')
    except Exception as e:
        print(f'Error accessing {url}: {e}')
""}

