        print(f'Disaster indicators found: {disaster_indicators[:5]}')

    # Look for specific event descriptions
    event_matches = re.findall(r'July 15,? 2008[^.!?]*[.!?]', response.text)
    for match in event_matches[:3]:
        print(f'Event mentioned: {match.strip()}')

    # Try to find any major industrial accidents
    industrial_accidents = re.findall(r'(pipeline|factory|chemical|industrial)[^.!?]*explosion[^.!?]*[.!?]', response.text, re.IGNORECASE)
    for accident in industrial_accidents[:2]:
        print(f'Industrial accident: {accident.strip()}')

except Exception as e:
    print(f'Error in search: {e}')

# Try a different approach - search for major pipeline explosions in 2008
